def quadro_sobreposicao_png(numero):
    """Retorna PNG RGBA esparso do quadro 1..47; quadro 0 não tem sobreposição."""
    numero = numero % NUM_FRAMES
    if numero == 0:
        return b''
    result = base64.b85decode(_PNG_B85[numero])
    if hashlib.sha256(result).hexdigest() != OVERLAY_SHA256[numero]:
        raise ValueError("Quadro da Justiça Holográfica corrompido")
    return result
